def MinimumProductGap(n):
    primes = [2]
    sieve = [True for i in range(n+1)]

    sqrt_n = int(n ** 0.5)
    for p in range(3, sqrt_n + 1):
        if sieve[p]:
            primes.append(p)
            for i in range(p*p, n + 1, p):
